/* OpenIC-assets-6.js - part 6 of 7 of the game icons for Open IC Creator's in-game window: icon sheets as data: URIs. OpenIC.iss loads the parts into the window's page
   (ISXOgreX.UI:EvalFile) one at a time once the window is open. Built by tools/build-window.js. The icons are
   EverQuest II's own art (Daybreak Game Company). */
(function () {
  var L = window.OpenIC_LIB;
  if (!L || !L.IC) return;
  var st = document.getElementById('openic-icon-sheets-6');
  if (!st) { st = document.createElement('style'); st.id = 'openic-icon-sheets-6'; (document.head || document.body).appendChild(st); }
  st.textContent = ".oic-sp-28{background-image:url(data:image/png;base64,);}\n.oic-sp-29{background-image:url(data:image/png;base64,);}\n.oic-sp-30{background-image:url(data:image/png;base64,);}\n.oic-sp-31{background-image:url(data:image/png;base64,);}\n.oic-sp-32{background-image:url(data:image/png;base64,);}\n.oic-sp-33{background-image:url(data:image/png;base64,);}\n.oic-sp-34{background-image:url(data:image/png;base64,);}\n.oic-it-1{background-image:url(data:image/png;base64,);}\n.oic-it-2{background-image:url(data:image/png;base64,);}\n";
  if (typeof window.ogreUISet === 'function') window.ogreUISet('openic', 'openic-assets-got', '6/7');
})();
